export default function ArticlePage({ slug }: { slug: string }) {
  return (
+   <Suspense fallback={<FullPageSpinner />}>
      <ArticleLayout>
        <ArticleHeader slug={slug} />        {/* title/meta, ~90ms */}
        <ArticleBody slug={slug} />          {/* the article, ~250ms */}
+       <RelatedArticles slug={slug} />      {/* cross-sell, ~1.5s slow API */}
+       <CommentThread slug={slug} />        {/* comments, ~1.2s */}
      </ArticleLayout>
+   </Suspense>
  );
}
// All four regions now share one route-root boundary.
